import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
// Font Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema & Types ---



export type ChartAnimationProps = Record<string, any>;

// --- Constants & Data ---

const DEFAULT_CHART_DATA = [
  { year: "2018", values: [10, 8, 5] }, // [Bottom(Product 3), Middle(Product 2), Top(Product 1)]
  { year: "2019", values: [8, 8, 4] },
  { year: "2020", values: [15, 10, 5] },
  { year: "2021", values: [18, 14, 8] },
  { year: "2022", values: [22, 20, 8] },
];

const ChartAnimation: React.FC<ChartAnimationProps> = ({
  backgroundColor = "#E6EBF5",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "COMPARE SALES STRATEGY",
  legendLabels = ["Product 01", "Product 02", "Product 03"],
  barColors = ["#00449E", "#349CD4", "#6DD6DA"],
  gridMax = 50,
  animationSpeed = 1,
}) => {
  useFontLoader(["Poppins", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Animation Drivers ---
  
  // Title slide in
  const titleSpring = spring({
    frame,
    fps,
    delay: 5,
    config: { damping: 20 },
  });
  
  const titleOffset = interpolate(titleSpring, [0, 1], [-100, 0]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);

  // Legend stagger
  const legendOpacities = legendLabels.map((_, i) => {
    return spring({
      frame,
      fps,
      delay: 15 + i * 5,
      config: { mass: 0.5 },
    });
  });

  // Chart Grid fade in
  const gridOpacity = interpolate(
    frame, 
    [10, 30], 
    [0, 1], 
    { extrapolateRight: "clamp" }
  );

  // Background Circles (Swooshes)
  const bgCircleScale = spring({
    frame, 
    fps, 
    config: { mass: 3, damping: 50 }
  });

  // --- Layout Calculations ---

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Reverse colors for legend to match visual order (Top Product is Darkest)
  // In our data, index 0 is bottom, index 2 is top.
  // Visual Legend: Top (Product 1 - Dark) -> Bottom (Product 3 - Light)
  // Data: [Light, Med, Dark] structure in stacked array usually goes bottom-up visually in code logic
  // but we want visual match:
  // Legend 1: Dark Blue (Product 01)
  // Legend 2: Med Blue (Product 02)
  // Legend 3: Light Blue (Product 03)
  
  // To match image:
  // Top segment of bar = Dark Blue (barColors[0])
  // Mid segment of bar = Med Blue (barColors[1])
  // Bot segment of bar = Light Blue (barColors[2])
  
  // The data structure values need to map to these colors.
  // DEFAULT_CHART_DATA values are [Bottom, Mid, Top] so [Product 3, Product 2, Product 1]
  // Colors array passed in prop is [Dark, Med, Light] (matching legend order)
  // So:
  // Segment 0 (Bottom) uses barColors[2]
  // Segment 1 (Middle) uses barColors[1]
  // Segment 2 (Top)    uses barColors[0]

  const chartHeight = height * 0.65;
  const chartWidth = width * 0.55;
  const maxVal = gridMax;

  // Generate grid lines (0, 10, 20, 30, 40, 50)
  const gridStep = 10;
  const gridLines = [];
  for (let i = 0; i <= maxVal; i += gridStep) {
    gridLines.push(i);
  }

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        color: "#1a1a1a",
        overflow: "hidden",
      }}
    >
      {/* --- Background Swooshes --- */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: width,
          height: height,
          pointerEvents: "none",
          transform: `scale(${bgCircleScale})`,
          transformOrigin: "center",
          opacity: 0.5,
        }}
      >
        <circle cx="50" cy="50" r="300" fill="none" stroke="white" strokeWidth="40" opacity="0.4" />
        <circle cx="50" cy="50" r="250" fill="none" stroke="white" strokeWidth="20" opacity="0.3" />
        <circle cx={width - 50} cy={height - 50} r="400" fill="none" stroke="white" strokeWidth="60" opacity="0.2" />
      </svg>

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          padding: `0 ${width * 0.05}px`,
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        {/* --- Left Panel: Title & Legend --- */}
        <div style={{ width: "35%", display: "flex", flexDirection: "column", gap: 60 }}>
          
          {/* Title */}
          <h1
            style={{
              fontFamily: "Poppins, sans-serif",
              fontSize: 80,
              fontWeight: 700,
              lineHeight: 1.2,
              margin: 0,
              transform: `translateX(${titleOffset}px)`,
              opacity: titleOpacity,
            }}
          >
            {titleText.split(" ").map((word, i) => (
              <span key={i} style={{ display: "block" }}>{word}</span>
            ))}
          </h1>

          {/* Legend */}
          <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
            {legendLabels.map((label, i) => (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 20,
                  opacity: legendOpacities[i],
                  transform: `translateY(${interpolate(legendOpacities[i], [0, 1], [20, 0])}px)`,
                }}
              >
                <div
                  style={{
                    width: 40,
                    height: 40,
                    backgroundColor: barColors[i], // Matches visual order Top->Bottom
                    borderRadius: 4,
                  }}
                />
                <span style={{ fontSize: 32, fontWeight: 600 }}>{label}</span>
              </div>
            ))}
          </div>
        </div>

        {/* --- Right Panel: Chart --- */}
        <div
          style={{
            width: chartWidth,
            height: chartHeight,
            position: "relative",
            opacity: gridOpacity,
          }}
        >
          {/* Grid Lines */}
          {gridLines.map((val) => {
            const bottomPos = (val / maxVal) * 100;
            return (
              <div
                key={val}
                style={{
                  position: "absolute",
                  bottom: `${bottomPos}%`,
                  left: 0,
                  width: "100%",
                  height: 1, // Line thickness
                  display: "flex",
                  alignItems: "center",
                }}
              >
                {/* Y-Axis Label */}
                <span
                  style={{
                    position: "absolute",
                    left: -50,
                    fontSize: 24,
                    fontWeight: 700,
                    color: "#333",
                    width: 40,
                    textAlign: "right",
                  }}
                >
                  {val}
                </span>
                {/* Line */}
                <div
                  style={{
                    width: "100%",
                    height: 2,
                    backgroundColor: "#cbd5e1",
                  }}
                />
              </div>
            );
          })}

          {/* Bars Container */}
          <div
            style={{
              position: "absolute",
              bottom: 0,
              left: 0,
              width: "100%",
              height: "100%",
              display: "flex",
              justifyContent: "space-between", // Distribute bars evenly
              alignItems: "flex-end",
              paddingLeft: 20, // Offset from Y-axis
            }}
          >
            {DEFAULT_CHART_DATA.map((data, index) => {
              // Values: [Bottom, Middle, Top] in data
              // Colors: [Top, Middle, Bottom] in props
              // Map: data.values[0] (Bottom) -> barColors[2]
              //      data.values[1] (Middle) -> barColors[1]
              //      data.values[2] (Top)    -> barColors[0]
              
              const totalValue = data.values.reduce((a, b) => a + b, 0);
              const heightPercentage = (totalValue / maxVal) * 100;
              
              // Animation for this bar
              const barGrowth = spring({
                frame,
                fps,
                delay: 20 + index * (10 / animationSpeed),
                config: { damping: 15, mass: 0.6 },
              });

              return (
                <div
                  key={data.year}
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    height: "100%", // Full height container to position year label
                    justifyContent: "flex-end",
                    width: "14%", // Width of each column area
                  }}
                >
                  {/* The Stacked Bar */}
                  <div
                    style={{
                      width: "100%",
                      height: `${heightPercentage}%`,
                      display: "flex",
                      flexDirection: "column-reverse", // Bottom data at bottom
                      transformOrigin: "bottom center",
                      transform: `scaleY(${barGrowth})`,
                    }}
                  >
                    {data.values.map((val, segIndex) => {
                      // Logic to map segment index to color
                      // segIndex 0 = Bottom -> Color 2
                      // segIndex 1 = Mid    -> Color 1
                      // segIndex 2 = Top    -> Color 0
                      const colorIndex = 2 - segIndex;
                      const isTopSegment = segIndex === data.values.length - 1;
                      
                      // Calculate height relative to the *stack*
                      // We need flex-basis or percentage of the *stack* height
                      const segmentHeightPercent = (val / totalValue) * 100;

                      return (
                        <div
                          key={segIndex}
                          style={{
                            width: "100%",
                            height: `${segmentHeightPercent}%`,
                            backgroundColor: barColors[colorIndex],
                            borderTopLeftRadius: isTopSegment ? 15 : 0,
                            borderTopRightRadius: isTopSegment ? 15 : 0,
                          }}
                        />
                      );
                    })}
                  </div>

                  {/* Year Label */}
                  <span
                    style={{
                      marginTop: 20,
                      fontSize: 24,
                      fontWeight: 700,
                      opacity: interpolate(barGrowth, [0, 1], [0, 1]),
                      transform: `translateY(${interpolate(barGrowth, [0, 1], [10, 0])}px)`,
                    }}
                  >
                    {data.year}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ChartAnimation;